        .data(data),
        .q(q)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Task to check output against expected using case inequality (as required)
    task check_output(input [63:0] exp);
        begin
            @(posedge clk);
            #1; // small delay to sample after clock edge
            if (q !== exp) begin
                $display("FAIL: Time=%0t | load=%b ena=%b amt=%b data=%h | q=%h, expected=%h", 
                         $time, load, ena, amount, data, q, exp);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        load = 0;
        ena = 0;
        amount = 2'b00;
        data = 64'h0;

        // 1. Test synchronous load
        @(posedge clk);
        load = 1;
        data = 64'h8000_0000_0000_0001; // Sign bit set (1), LSB set (1)
        expected = 64'h8000_0000_0000_0001;
        check_output(expected);

        // Turn off load
        load = 0;

        // 2. Test shift left by 1 (amount = 2'b00)
        // Expected: {q[62:0], 1'b0} -> 0x0000_0000_0000_0002
        ena = 1;
        amount = 2'b00;
        expected = {expected[62:0], 1'b0};
        check_output(expected);

        // 3. Test shift left by 8 (amount = 2'b01)
        // Expected: {q[55:0], 8'b0}
        amount = 2'b01;
        expected = {expected[55:0], 8'b0};
        check_output(expected);

        // 4. Reload with negative number for arithmetic right shift testing
        load = 1;
        data = 64'h8000_0000_0000_0000; // Sign bit = 1, others = 0
        expected = 64'h8000_0000_0000_0000;
        check_output(expected);

        load = 0;
        ena = 1;

        // 5. Test arithmetic shift right by 1 (amount = 2'b10)
        // Expected: {q[63], q[63:1]} -> sign extension
        amount = 2'b10;
        expected = {expected[63], expected[63:1]};
        check_output(expected);

        // 6. Test arithmetic shift right by 8 (amount = 2'b11)
        // Let's check the candidate RTL's behavior for right shift by 8:
        // Candidate has: q <= {q[63], q[63:8]}; which is 64 bits total (1 + 56 = 57? Wait!)
        // Let's verify width in RTL: {q[63] (1 bit), q[63:8] (56 bits)} = 57 bits!
        // This is a classic RTL truncation/width mismatch flaw in Verilog!
        amount = 2'b11;
        // Let's see what the DUT actually produces vs what is mathematically expected for ASr 8.
        // Mathematically expected arithmetic right shift by 8 with sign extension:
        // 8 bits of sign extension at top: {8{expected[63]}, expected[63:8]} -> 8 + 56 = 64 bits.
        // Let's calculate standard expected based on correct arithmetic shift:
        expected = {{8{expected[63]}}, expected[63:8]};
        check_output(expected); // This will expose the bug if the RTL concatenates improperly!

        // 7. Test disabled state (ena = 0)
        ena = 0;
        data = 64'hFFFF_FFFF_FFFF_FFFF;
        @(posedge clk);
        #1;
        // q should remain unchanged despite new data and clk edges
        if (q !== expected) begin
            $display("FAIL: Ena=0 check failed. q=%h, expected=%h", q, expected);
            errors = errors + 1;
        end

        // Finish up
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
